create table public.global_gifts(id uuid primary key default gen_random_uuid(),seed_quantity integer not null check(seed_quantity>0),status text not null default 'draft' check(status in('draft','published','ended')),created_at timestamptz not null default now(),published_at timestamptz,ended_at timestamptz,created_by uuid references auth.users(id));
create table public.global_gift_claims(gift_id uuid not null references public.global_gifts(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,claimed_at timestamptz not null default now(),primary key(gift_id,profile_id));
alter table public.global_gifts enable row level security; alter table public.global_gift_claims enable row level security; revoke all on public.global_gifts,public.global_gift_claims from public,anon,authenticated;
insert into public.global_gifts(seed_quantity,status,published_at) values(100,'published',now());
create or replace function public.list_pending_global_gifts() returns table(id uuid,seed_quantity integer) language sql security definer set search_path=public,auth as $$select g.id,g.seed_quantity from public.global_gifts g where g.status='published' and not exists(select 1 from public.global_gift_claims c join public.profiles p on p.id=c.profile_id where c.gift_id=g.id and p.auth_user_id=auth.uid()) order by g.published_at$$;
create or replace function public.claim_global_gift(gift_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$declare pid uuid:=public.current_profile_id(); amount integer; begin if pid is null then raise exception 'Authentication required' using errcode='28000';end if; select seed_quantity into amount from public.global_gifts where id=gift_id and status='published' for update;if amount is null then raise exception 'Gift unavailable' using errcode='22023';end if;insert into public.global_gift_claims(gift_id,profile_id) values(gift_id,pid) on conflict do nothing;if not found then raise exception 'Gift already claimed' using errcode='P0001';end if;insert into public.profile_seed_balances(profile_id,quantity) values(pid,amount) on conflict(profile_id) do update set quantity=profile_seed_balances.quantity+excluded.quantity,updated_at=now();return jsonb_build_object('seedQuantity',amount);end$$;
create or replace function public.admin_create_global_gift(target_seed_quantity integer) returns jsonb language plpgsql security definer set search_path=public,auth as $$declare id uuid;begin perform public.assert_asset_admin_actor(auth.uid());if target_seed_quantity<1 then raise exception 'Seed quantity must be positive' using errcode='22023';end if;insert into public.global_gifts(seed_quantity,created_by) values(target_seed_quantity,auth.uid()) returning global_gifts.id into id;return jsonb_build_object('id',id);end$$;
create or replace function public.admin_set_global_gift_status(target_gift_id uuid,target_status text) returns void language plpgsql security definer set search_path=public,auth as $$begin perform public.assert_asset_admin_actor(auth.uid());update public.global_gifts set status=target_status,published_at=case when target_status='published' then coalesce(published_at,now()) else published_at end,ended_at=case when target_status='ended' then now() else ended_at end where id=target_gift_id;end$$;
grant execute on function public.list_pending_global_gifts(),public.claim_global_gift(uuid),public.admin_create_global_gift(integer),public.admin_set_global_gift_status(uuid,text) to authenticated;
